draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw an apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // add a stem
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2, H/2 - 70);
  ctx.stroke();

  // add a leaf
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 - 60);
  ctx.lineTo(W/2 + 40, H/2 - 40);
  ctx.lineTo(W/2, H/2 - 50);
  ctx.fill();
  ctx.stroke();

  // draw a stick figure eating the apple
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2 - 20, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2);
  ctx.lineTo(W/2 + 100, H/2 + 50);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 20);
  ctx.lineTo(W/2 + 80, H/2 + 40);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 20);
  ctx.lineTo(W/2 + 120, H/2 + 40);
  ctx.stroke();

  // make the stick figure move up and down
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 100, H/2 + 70 + 20 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
